files.content:
:root {
  --bg: #1b1f2a;
  --card: #262c3a;
  --accent: #4f9cf9;
  --on: #ffd257;
  --off: #3a4256;
  --text: #eef2f8;
  --muted: #9aa4b8;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: radial-gradient(circle at 50% 0%, #2a3142, var(--bg));
  color: var(--text);
  font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

.card {
  background: var(--card);
  border-radius: 18px;
  padding: 28px 24px;
  width: 100%;
  max-width: 380px;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  text-align: center;
}

.card-header h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.status {
  margin: 18px 0 14px;
  min-height: 44px;
}

.moves {
  margin: 0;
  font-weight: 600;
}

.message {
  margin: 6px 0 0;
  min-height: 1.5em;
  color: var(--on);
  font-weight: 600;
}

.board {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 0 auto 22px;
}

.cell {
  aspect-ratio: 1;
  border: none;
  border-radius: 12px;
  background: var(--off);
  cursor: pointer;
  transition: background 0.15s, transform 0.08s, box-shadow 0.15s;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.04);
}

.cell:hover { background: #465073; }

.cell:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.cell:active { transform: scale(0.94); }

.cell.on {
  background: var(--on);
  box-shadow: 0 0 18px rgba(255, 210, 87, 0.55);
}

.cell.on:hover { background: #ffe08a; }

.btn {
  width: 100%;
  padding: 14px;
  font: inherit;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.15s, transform 0.08s;
}

.btn:hover { background: #6fb0ff; }
.btn:active { transform: scale(0.97); }
.btn:focus-visible {
  outline: 3px solid var(--on);
  outline-offset: 3px;
}

@media (max-width: 400px) {
  .card { padding: 22px 16px; }
  .board { gap: 8px; }
}

(function () {
  "use strict";

  const SIZE = 3;
  const boardEl = document.getElementById("board");
  const moveEl = document.getElementById("moveCount");
  const messageEl = document.getElementById("message");
  const newBtn = document.getElementById("newPuzzle");

  let grid = [];
  let moves = 0;
  let won = false;
  const cells = [];

  function buildBoard() {
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "cell";
        btn.setAttribute("aria-label", `Row ${r + 1}, column ${c + 1}`);
        btn.addEventListener("click", () => handleClick(r, c));
        boardEl.appendChild(btn);
        cells.push(btn);
      }
    }
  }

  function toggle(r, c) {
    if (r < 0 || r >= SIZE || c < 0 || c >= SIZE) return;
    grid[r][c] = !grid[r][c];
  }

  function applyMove(r, c) {
    toggle(r, c);
    toggle(r - 1, c);
    toggle(r + 1, c);
    toggle(r, c - 1);
    toggle(r, c + 1);
  }

  function isSolved() {
    return grid.every((row) => row.every((v) => !v));
  }

  function render() {
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const btn = cells[r * SIZE + c];
        const on = grid[r][c];
        btn.classList.toggle("on", on);
        btn.setAttribute("aria-pressed", on ? "true" : "false");
      }
    }
    moveEl.textContent = String(moves);
  }

  function handleClick(r, c) {
    if (won) return;
    applyMove(r, c);
    moves++;
    render();
    if (isSolved()) {
      won = true;
      messageEl.textContent = `You win! Solved in ${moves} move${moves === 1 ? "" : "s"}.`;
    }
  }

  function newPuzzle() {
    grid = Array.from({ length: SIZE }, () => Array(SIZE).fill(false));
    moves = 0;
    won = false;
    messageEl.textContent = "";

    // Random scramble from solved state guarantees a solvable puzzle.
    let scrambles = 5 + Math.floor(Math.random() * 5);
    while (scrambles > 0) {
      const r = Math.floor(Math.random() * SIZE);
      const c = Math.floor(Math.random() * SIZE);
      applyMove(r, c);
      scrambles--;
    }
    if (isSolved()) applyMove(1, 1);

    render();
  }

  buildBoard();
  newBtn.addEventListener("click", newPuzzle);
  newPuzzle();
})();
